const summarizeAssets = `-- name: SummarizeAssets :one
SELECT count(*)::int AS total, COALESCE(SUM(a.cost), 0)::numeric(18,3) AS cost, COALESCE(SUM(a.accum_depr), 0)::numeric(18,3) AS accum
  FROM fa_assets a
 WHERE a.tenant_id = $1 AND a.property_id = $2
   AND ($3::bigint IS NULL OR a.category_id = $3)
   AND ($4::bigint IS NULL OR a.location_id = $4)
   AND ($5::bigint IS NULL OR a.department_id = $5)
   AND ($6::text IS NULL OR a.status = $6)
   AND ($7::text IS NULL OR a.number ILIKE '%' || $7 || '%' OR a.name ILIKE '%' || $7 || '%' OR a.serial_no ILIKE '%' || $7 || '%')
   AND ($8::date IS NULL OR (a.warranty_until IS NOT NULL AND a.warranty_until <= $8))
   AND ($9::boolean IS NULL OR ((a.life_months IS NOT NULL AND a.accum_depr >= a.cost - a.residual_value) = $9))
`

type SummarizeAssetsParams struct {
	TenantID         int64
	PropertyID       int64
	CategoryID       *int64
	LocationID       *int64
	DepartmentID     *int64
	Status           *string
	Q                *string
	WarrantyBefore   *civil.Date
	FullyDepreciated *bool
}

type SummarizeAssetsRow struct {
	Total int32
	Cost  decimal.Decimal
	Accum decimal.Decimal
}

func (q *Queries) SummarizeAssets(ctx context.Context, arg SummarizeAssetsParams) (SummarizeAssetsRow, error) {
	row := q.db.QueryRow(ctx, summarizeAssets,
		arg.TenantID,
		arg.PropertyID,
		arg.CategoryID,
		arg.LocationID,
		arg.DepartmentID,
		arg.Status,
		arg.Q,
		arg.WarrantyBefore,
		arg.FullyDepreciated,
	)
	var i SummarizeAssetsRow
	err := row.Scan(&i.Total, &i.Cost, &i.Accum)
	return i, err
}

